  const stage=selectedStage===null?currentStage:selectedStage===currentStage||initialItem&&(initialItem.stageId||initialItem.stage)===selectedStage||showLater||stages.indexOf(selectedStage)<stages.indexOf(currentStage||'')?selectedStage:currentStage;
  const items=stage?stageItems(data,p,stage):[],archivedItems=data.workItems.filter(item=>item.projectId===p.id&&item.archived),required=items.filter(w=>w.required!==false),done=required.filter(w=>w.status==='Completed').length,issues=data.helpRequests.filter(h=>h.projectId===p.id&&h.status!=='Resolved');
  const laterItems=currentStage?data.workItems.filter(item=>item.projectId===p.id&&!item.archived&&stages.indexOf(item.stageId||item.stage)>stages.indexOf(currentStage)&&((item.progress>0&&item.status!=='Completed')||activeHelpForItem(data,item.id))):[];
  const laterHelp=laterItems.filter(item=>Boolean(activeHelpForItem(data,item.id))).length;
  const canRevealLater=canAdd&&currentStage!==null&&stages.indexOf(currentStage)<stages.length-1;
  useEffect(()=>{setSelectedStage(initialItem?.stageId||initialItem?.stage||currentProjectStage(data,p));setShowLater(Boolean(initialItem&&currentStage&&stages.indexOf(initialItem.stageId||initialItem.stage)>stages.indexOf(currentStage)));setDetail(initialHelp||!openDetailOnEntry?null:initialItem||null);setIssue(initialHelp||null)},[initialWorkItemId,initialHelpId,projectId,openDetailOnEntry]);
