    <nav className="simple-stages" aria-label="Project sections">{stages.filter((name,index)=>index<=stages.indexOf(currentStage||'')||!currentStage||showLater).map(name=>{const complete=projectStageComplete(data,p,name);return <button className={`${stage===name?'selected':''} ${complete?'complete':''} ${name===currentStage?'current':''}`} key={name} onClick={()=>setSelectedStage(name)}><i>{complete?<Check size={14}/>:String(stages.indexOf(name)+1).padStart(2,'0')}</i><span>{name}<small>{complete?'Completed':name===currentStage?'● CURRENT':''}</small></span></button>})}</nav>
